    "cat": "dyr",
    "title": "Fugl",
    "level": 1,
    "steps": [
      "Tegn en stor, rund pæreform med den smalle ende øverst til højre.",
      "Tegn en smal hale, der stikker skråt ned til venstre.",
      "Tegn en stor dråbeform som vinge inde i kroppens venstre side.",
      "Tegn to korte, buede fjerstreger inde i vingen.",
      "Tegn en lang, blød bue inde i kroppen fra hovedet ned mod brystet.",
      "Tegn et lille trekantet næb til højre med en streg i midten.",
      "Tegn et mørkt, rundt øje over næbbet. Lad en lille prik være hvid.",
      "Tegn to korte ben under maven med tre buede tæer på hver fod.",
      "Tegn en smal gren under tæerne med to skrå streger og runde ender.",
      "Skyg let inde i vingen og halen med små blyantstreger.",
      "Skyg let på hovedet, kroppen og grenen."
    ],
