    "id": "fluesvamp",
    "cat": "natur",
    "title": "Fluesvamp",
    "level": 2,
    "steps": [
      "Tegn let en stor hattebue øverst med en flad oval som underside.",
      "Tegn en lang oval til den store stok og en lodret hjælpelinje gennem svampen.",
      "Tegn hjælpeformer til den lille svamp nederst til højre og en bred oval til mosset.",
      "Følg den store hats yderkant med en tydelig streg.",
      "Tegn den store stoks sider og det bølgede skørt lige under hatten.",
      "Tegn den lille svamps hat, stok og bølgede skørt oven på hjælpeformerne.",
      "Tegn en bølget kant til mosset rundt om begge stokke.",
      "Tegn ujævne pletter på den store hat.",
      "Tegn ujævne pletter på den lille hat.",
      "Tegn enkelte streger under den store hat.",
      "Tegn én lille mosgren med korte sidegrene.",
      "Tegn små forgrenede mosgrene rundt om svampenes fødder.",
      "Tegn flere streger mellem de tidligere streger under hattene.",
      "Tegn små, lette streger langs kanterne af hattenes pletter.",
      "Tegn folder i skørterne og korte streger langs stokkene.",
      "Tegn små blade på én mosgren.",
      "Tegn små blade på resten af mosgrenene.",
      "Visk hjælpelinjerne let ud. Skyg let på hattene. Lad pletterne være lyse.",
      "Skyg let under hattene, på stokkene og i mosset.",
      "Gør skyggerne mørkere under hattene og mellem mosset. Lad pletterne på hattene være lyse."
    ],
