    "id": "elefant",
    "cat": "dyr",
    "title": "Elefant",
    "level": 3,
    "steps": [
      "Tegn en lys cirkel øverst til højre til hovedet. Lad en lille åbning være nederst.",
      "Tegn store ører og en oval til kroppen.",
      "Tegn en lang, bøjet form til snablen.",
      "Tegn fire lange benformer med fodovaler nederst og en tynd hale bag kroppen til venstre.",
      "Tegn hovedets og snablens kanter.",
      "Tegn to lange, spidse stødtænder med buede streger.",
      "Tegn begge ørers bølgede omrids på hver side af hovedet.",
      "Tegn kroppens buede ryg til venstre, den korte mave og halen bagpå.",
      "Tegn de to nærmeste ben med brede fødder.",
      "Tegn de to ben bagved og deres fødder.",
      "Tegn et øje, små folder i ansigtet og hår på halespidsen.",
      "Tegn buede ringe på snablen.",
      "Tegn tånegle og små folder på kroppen og benene.",
      "Tegn fine rynker inde i ørerne.",
      "Tegn fine rynker på hovedet og snablen mellem de tidligere ringe.",
      "Tegn små rynker langs kroppens og benenes kanter.",
      "Tegn et lille område med korte streger, der krydser hinanden.",
      "Tegn flere krydsende rynker på kroppen og benene.",
      "Visk hjælpelinjerne let ud. Skyg let på hovedet, ørerne og snablen.",
      "Skyg let på kroppen og benene samt under fødderne.",
      "Gør skyggerne på elefanten mørkere, især under ørerne og mellem benene. Tegn rynkerne tydeligere."
    ],
